#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[])
{
    // Expect exactly two numeric arguments: n (size) and k (step)
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    long k = strtol(argv[2], &endptr, 10);
    if (endptr == argv[2] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    // Range limits observed in the original binary
    if (n > 1000000L || k > 1000000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // Josephus problem: iterative solution (0‑based index)
    long result = 0;
    for (long i = 2; i <= n; ++i) {
        result = (result + k) % i;
    }
    printf("%ld\n", result + 1);
    return 0;
}
